import {
  assertTelemetryMode,
  TelemetryPolicyMismatchError,
} from '../config/telemetryPolicy';
import { readEditorAccessToken } from './editorSession';
import {
  createEditorUrl,
  EDITOR_ACCESS_TOKEN_HEADER,
  isEditorApiPath,
} from '../utils/editorAccess';
import { RIVET_VERSION } from '../config/telemetry';
import {
  isPidAlive,
  readHandshakeResult,
  removeHandshake,
  type ServerHandshake,
} from './serverHandshake';
import {
  CALLER_SESSION_HEADER,
  QUEUE_ACCESS_TOKEN_HEADER,
} from '../utils/queueAccess';
import type { CallerHandoff } from './handoff';
import { z } from 'zod';
import {
  assertPluginContext,
  getPluginName,
  PluginContextMismatchError,
} from '../hosts/pluginContext';

const HEALTH_PING_TIMEOUT_MS = 2_000;
const REQUEST_TIMEOUT_MS = 30_000;

export type AttachedServer = {
  baseUrl: string;
  handshake: ServerHandshake;
};

export type ServerResponse<T = unknown> = {
  status: number;
  body: T;
};

export type ServerAttachFailureReason =
  | 'handshake_missing'
  | 'handshake_invalid'
  | 'process_not_running'
  | 'health_check_failed';

export type ServerAttachResult =
  | { status: 'attached'; server: AttachedServer }
  | { status: 'unavailable'; reason: ServerAttachFailureReason };

export const isServerHealthy = async (
  rivetPort: number,
  env: NodeJS.ProcessEnv = process.env,
): Promise<boolean> => {
  try {
    const response = await fetch(`http://127.0.0.1:${rivetPort}/api/health`, {
      signal: AbortSignal.timeout(HEALTH_PING_TIMEOUT_MS),
    });
    if (!response.ok) return false;
    const health = z
      .object({
        pluginName: z.string().optional(),
        telemetryMode: z.unknown().optional(),
      })
      .safeParse(await response.json().catch(() => null));
    if (health.success) {
      assertPluginContext(health.data.pluginName, env);
      assertTelemetryMode(health.data.telemetryMode, env);
    } else if (getPluginName(env)) {
      return false;
    }
    return true;
  } catch (error) {
    if (
      error instanceof PluginContextMismatchError ||
      error instanceof TelemetryPolicyMismatchError
    )
      throw error;
    return false;
  }
};

let attachCache: Map<string, AttachedServer> | null = null;

export const enableAttachCache = (): void => {
  attachCache ??= new Map();
};

export const invalidateAttachCache = (): void => {
  attachCache?.clear();
};

export const inspectServer = async (
  projectPath: string,
  env: NodeJS.ProcessEnv = process.env,
): Promise<ServerAttachResult> => {
  const cached = attachCache?.get(projectPath);
  const handshakeResult = readHandshakeResult(projectPath);
  if (handshakeResult.status !== 'found') {
    return {
      status: 'unavailable',
      reason:
        handshakeResult.status === 'missing'
          ? 'handshake_missing'
          : 'handshake_invalid',
    };
  }
  const { handshake } = handshakeResult;
  if (!isPidAlive(handshake.pid)) {
    removeHandshake(projectPath, handshake.pid);
    return { status: 'unavailable', reason: 'process_not_running' };
  }
  assertPluginContext(handshake.pluginName, env);
  assertTelemetryMode(handshake.telemetryMode, env);
  if (
    cached &&
    cached.handshake.pid === handshake.pid &&
    cached.handshake.startedAt === handshake.startedAt &&
    cached.handshake.rivetPort === handshake.rivetPort &&
    cached.handshake.rivetVersion === handshake.rivetVersion &&
    cached.handshake.pluginName === handshake.pluginName &&
    cached.handshake.telemetryMode === handshake.telemetryMode &&
    cached.handshake.queueAccessToken === handshake.queueAccessToken
  ) {
    return { status: 'attached', server: cached };
  }
  attachCache?.delete(projectPath);
  if (!(await isServerHealthy(handshake.rivetPort, env))) {
    return { status: 'unavailable', reason: 'health_check_failed' };
  }
  const attached: AttachedServer = {
    baseUrl: `http://127.0.0.1:${handshake.rivetPort}`,
    handshake,
  };
  attachCache?.set(projectPath, attached);
  return { status: 'attached', server: attached };
};

export const attachToServer = async (
  projectPath: string,
  env: NodeJS.ProcessEnv = process.env,
): Promise<AttachedServer | null> => {
  const result = await inspectServer(projectPath, env);
  return result.status === 'attached' ? result.server : null;
};

export type ServerRequestOptions = {
  method?: 'GET' | 'POST';
  body?: unknown;
  timeoutMs?: number;
  callerSession?: string;
  expectedAccountId?: string;
};

export const requestServer = async <T = unknown>(
  attached: AttachedServer,
  path: string,
  options: ServerRequestOptions = {},
): Promise<ServerResponse<T>> => {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Rivet-Client-Version': RIVET_VERSION,
  };
  if (attached.handshake.queueAccessToken) {
    headers[QUEUE_ACCESS_TOKEN_HEADER] = attached.handshake.queueAccessToken;
  }
  if (options.callerSession) {
    headers[CALLER_SESSION_HEADER] = options.callerSession;
  }
  if (options.expectedAccountId) {
    headers['X-Rivet-Account-Id'] = options.expectedAccountId;
  }
  if (isEditorApiPath(path, options.method)) {
    const token = readEditorAccessToken({
      pid: attached.handshake.pid,
      port: attached.handshake.rivetPort,
      projectPath: attached.handshake.projectPath,
      startedAt: attached.handshake.startedAt,
    });
    if (token) headers[EDITOR_ACCESS_TOKEN_HEADER] = token;
  }
  const response = await fetch(`${attached.baseUrl}${path}`, {
    redirect: 'error',
    method: options.method ?? 'GET',
    headers,
    ...(options.body === undefined
      ? {}
      : { body: JSON.stringify(options.body) }),
    signal: AbortSignal.timeout(options.timeoutMs ?? REQUEST_TIMEOUT_MS),
  });
  const body = (await response.json().catch(() => ({}))) as T;
  return { status: response.status, body };
};

export const editorUrlFor = (attached: AttachedServer): string => {
  const token = readEditorAccessToken({
    pid: attached.handshake.pid,
    port: attached.handshake.rivetPort,
    projectPath: attached.handshake.projectPath,
    startedAt: attached.handshake.startedAt,
  });
  if (!token)
    throw new Error('Restart this project editor to authorize browser access.');
  return createEditorUrl({ port: attached.handshake.rivetPort, token });
};

export const callerSessionOf = (
  handoff: CallerHandoff | null,
): string | undefined => handoff?.session ?? undefined;
